//! `--output table` / `yaml` / `yaml-stream` against fixtures generated by
//! the reference AWS CLI's formatters (`tests/fixtures/output/generate.py`).

mod common;

use awsr::output::{OutputFormat, TableStyle, write};
use serde_json::Value as J;

fn render(format: OutputFormat, data: &J) -> Result<String, String> {
    let style = TableStyle {
        title: "OperationName".into(),
        terminal_width: 80,
        color: false,
    };
    let mut buf = Vec::new();
    write(format, data, &style, &mut buf).map_err(|e| e.to_string())?;
    Ok(String::from_utf8(buf).unwrap())
}

#[test]
fn formatters_match_awscli() {
    let cases = common::read_json(&common::fixtures().join("output/cases.json"));
    let mut failures = Vec::new();
    let mut checked = 0;
    for case in cases.as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let data = &case["data"];
        let mut check = |what: &str, format: OutputFormat, expected: Result<&str, &str>| {
            checked += 1;
            let got = render(format, data);
            let ok = match (&got, expected) {
                (Ok(g), Ok(e)) => g == e,
                (Err(g), Err(e)) => g == e,
                _ => false,
            };
            if !ok {
                failures.push(format!(
                    "{name} ({what}):\n--- expected\n{}\n--- got\n{}",
                    match expected {
                        Ok(e) => e.to_string(),
                        Err(e) => format!("error: {e}"),
                    },
                    match &got {
                        Ok(g) => g.clone(),
                        Err(g) => format!("error: {g}"),
                    }
                ));
            }
        };
        check(
            "yaml",
            OutputFormat::Yaml,
            Ok(case["yaml"].as_str().unwrap()),
        );
        check(
            "yaml-stream",
            OutputFormat::YamlStream,
            Ok(case["yaml_stream"].as_str().unwrap()),
        );
        if let Some(t) = case.get("table").and_then(J::as_str) {
            check("table", OutputFormat::Table, Ok(t));
        }
        if let Some(e) = case.get("table_error").and_then(J::as_str) {
            check("table", OutputFormat::Table, Err(e));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {checked} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn colorized_table() {
    let style = TableStyle {
        title: "Op".into(),
        terminal_width: 80,
        color: true,
    };
    let mut buf = Vec::new();
    write(
        OutputFormat::Table,
        &serde_json::json!({"A": {"B": "x"}}),
        &style,
        &mut buf,
    )
    .unwrap();
    let s = String::from_utf8(buf).unwrap();
    assert!(s.contains("\x1b[1m\x1b[34mx\x1b[0m"), "{s:?}");
    assert!(s.contains("\x1b[2m\x1b[33m|\x1b[0m"), "{s:?}");
}
